<?php
namespace App\Domain\Products;use App\Models\{Page,Product,Solution};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;final class ProductRelationManager {public function sync(Product $p,array $products,array $solutions,array $pages):void{if(in_array($p->id,$products,true))throw ValidationException::withMessages(['related_product_ids'=>'A product cannot relate to itself.']);foreach([$products,$solutions,$pages] as $ids)if(count($ids)!==count(array_unique($ids))||count($ids)>6)throw ValidationException::withMessages(['relations'=>'Relations must be unique and limited to six per type.']);if(Product::whereIn('id',$products)->whereNotNull('archived_at')->exists()||Solution::whereIn('id',$solutions)->whereNotNull('archived_at')->exists()||Page::whereIn('id',$pages)->whereNotNull('archived_at')->exists())throw ValidationException::withMessages(['relations'=>'Archived targets cannot be selected.']);DB::transaction(function()use($p,$products,$solutions,$pages){foreach([['relatedProducts',$products],['relatedSolutions',$solutions],['relatedPages',$pages]] as [$rel,$ids])$p->{$rel}()->sync(collect($ids)->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i+1]])->all());});ProductCache::forget($p->id);foreach($products as $id)ProductCache::forget($id);}}